import Foundation
import MacSanityCore

/// App caches: `~/Library/Caches/*` (and `/Library/Caches/*`), Electron/Chromium
/// caches inside Application Support, superseded versions apps keep around,
/// updater leftovers, and old logs and crash reports. Everything here is
/// regenerated by its app.
struct AppCachesDetector: Detector {
    let category = CleanerCategory.appCaches

    private struct Candidate {
        let path: String
        let owner: AppRecord?
        let ownerName: String
        var reason: String
        var safety: Safety
        let quitFirst: [String]
    }

    func scan(_ ctx: ScanContext) async -> [Finding] {
        var candidates: [Candidate] = []
        let catalogPaths = Set(Catalog.developer.flatMap(\.paths).flatMap { DiskIO.expand($0, home: ctx.home) })

        // 1. ~/Library/Caches and /Library/Caches entries, attributed to an app.
        for root in [ctx.home + "/Library/Caches", "/Library/Caches"] {
            let children = DiskIO.children(of: root).filter { !catalogPaths.contains($0) && !DiskIO.isSymlink($0) }
            let superseded = VersionedSiblings.superseded(children.map { ($0 as NSString).lastPathComponent })
            for path in children where ctx.isRemovable(path) {
                let name = (path as NSString).lastPathComponent
                // macOS services' plainly named caches (GeoServices, PassKit…) and
                // tool caches (sized by the Developer section) are never offered here.
                if KnownFolders.systemAndTools.contains(OrphanMatcher.normalize(name)) { continue }
                let owner = ctx.app(forBundleID: name) ?? ctx.app(named: name)
                // Caches of removed apps are claimed (with higher priority) by the
                // leftovers detector too; the claim resolver moves them there.
                var reason = "Cache"
                if superseded.contains(name) { reason = "Old version" }
                else if Catalog.isUpdaterLeftover(name) { reason = "Update leftover" }
                // Without a known owner we can't make sure it's not in use: review only.
                candidates.append(Candidate(path: path, owner: owner, ownerName: owner?.name ?? Self.prettyName(name),
                                            reason: reason,
                                            safety: owner == nil ? .review : .safe,
                                            quitFirst: owner.map { [$0.bundleID] } ?? []))
            }
        }

        // 2. Chromium/Electron caches inside Application Support/<App>/ (and one profile level down).
        let support = ctx.home + "/Library/Application Support"
        for appDir in DiskIO.children(of: support) where DiskIO.isDirectory(appDir) {
            let name = (appDir as NSString).lastPathComponent
            let owner = ctx.app(named: name) ?? ctx.app(forBundleID: name)
            var bases = [appDir]
            for child in DiskIO.children(of: appDir) where DiskIO.isDirectory(child) {
                let c = (child as NSString).lastPathComponent
                if c == "Default" || c.hasPrefix("Profile ") || c == "Partitions" { bases.append(child) }
                if c == "Partitions" { bases += DiskIO.children(of: child) }
            }
            for base in bases {
                for sub in Catalog.chromiumCacheFolders {
                    let path = base + "/" + sub
                    guard DiskIO.isDirectory(path), !DiskIO.isSymlink(path), ctx.isRemovable(path) else { continue }
                    candidates.append(Candidate(path: path, owner: owner, ownerName: owner?.name ?? name,
                                                reason: "Web cache", safety: .safe,
                                                quitFirst: owner.map { [$0.bundleID] } ?? []))
                }
            }
        }

        // 3. Old logs and crash reports (untouched for 30+ days).
        for root in [ctx.home + "/Library/Logs", "/Library/Logs"] {
            for path in DiskIO.children(of: root) where ctx.isRemovable(path) && !DiskIO.isSymlink(path) {
                let name = (path as NSString).lastPathComponent
                if name == "DiagnosticReports" {
                    for report in DiskIO.children(of: path) where ctx.days(since: DiskIO.modified(report)) >= 30 && ctx.isRemovable(report) {
                        candidates.append(Candidate(path: report, owner: nil, ownerName: "Crash reports",
                                                    reason: "Crash reports", safety: .safe, quitFirst: []))
                    }
                    continue
                }
                let owner = ctx.app(forBundleID: name) ?? ctx.app(named: name)
                candidates.append(Candidate(path: path, owner: owner, ownerName: owner?.name ?? Self.prettyName(name),
                                            reason: "Old logs", safety: .safe, quitFirst: []))
            }
        }

        let sizes = await DiskIO.sizes(candidates.map(\.path), cancel: ctx.cancel)
        // One finding per owning app, combining all its caches.
        var byOwner: [String: [Candidate]] = [:]
        for c in candidates {
            guard let s = sizes[c.path], s.allocated >= 1_000_000 else { continue }
            if c.reason == "Old logs", ctx.days(since: s.newest) < 30 { continue }
            byOwner[c.owner?.bundleID ?? c.ownerName, default: []].append(c)
        }
        return byOwner.map { key, cands in
            let owner = cands.first?.owner
            let items = cands.compactMap { c in sizes[c.path].map { FindingItem(path: c.path, size: $0.allocated, modified: $0.newest) } }
            var reasons = Array(Set(cands.map(\.reason))).sorted()
            if let used = owner?.lastUsed, ctx.days(since: used) >= Policies.unusedCacheOwnerDays {
                reasons.insert("Not opened in \(RelativeTime.describe(days: ctx.days(since: used)))", at: 0)
            }
            let needsAdmin = cands.contains { DiskIO.ownerUID($0.path) != ctx.uid }
            return Finding(
                id: Finding.makeID(category, key), category: category,
                title: cands.first?.ownerName ?? key,
                reason: reasons.joined(separator: " · "),
                afterRemoval: "Rebuilt by the app when needed; it may feel slower the first time.",
                safety: cands.map(\.safety).max() ?? .safe, items: items.sorted { $0.size > $1.size },
                group: owner == nil ? "Other caches" : "Apps",
                lastUsed: owner?.lastUsed ?? items.compactMap(\.modified).max(),
                iconPath: owner?.path, action: .trash,
                quitFirst: Array(Set(cands.flatMap(\.quitFirst))), needsAdmin: needsAdmin,
                details: owner == nil ? "No installed app was found for this cache, so it isn't preselected." : "")
        }
    }

    /// "com.vendor.App" → "App"; versioned or plain folder names stay as they are.
    static func prettyName(_ name: String) -> String {
        let parts = name.split(separator: ".")
        let isReverseDNS = parts.count >= 3 && parts[0].allSatisfy(\.isLetter) && parts[1].first?.isLetter == true
        return isReverseDNS ? OrphanMatcher.displayHint(name) : name
    }
}
